export const ollamaService = {
  async sendMessage(message, context, options = {}) {
    try {
      alert("send messege")
      const response = await fetch(`/api/chat/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: message,
          context: context
        })
      });
      alert(response)


      if (!response.ok) throw new Error(`Error: ${response.status}`);
      const data = await response.json();
      return data.response;
    } catch (error) {
      alert("error")
      alert(error.JSON.stringify)
      console.error('Error calling Django API:', error);
      throw error;
    }
  },

  async healthCheck() {
    // This health check might not work as expected anymore,
    // as it's still pointing to the Ollama service directly.
    // You might want to create a new health check endpoint in Django.
    try {
      const response = await fetch('http://localhost:11434/api/tags');
      return response.ok;
    } catch (error) {
      return false;
    }
  }
};
